   168→impl From<BeaconChainError> for GossipDataColumnError {
   169→    fn from(e: BeaconChainError) -> Self {
   170→        GossipDataColumnError::BeaconChainError(e.into())
   171→    }
   172→}
   173→
   174→impl From<BeaconStateError> for GossipDataColumnError {
   175→    fn from(e: BeaconStateError) -> Self {
   176→        GossipDataColumnError::BeaconChainError(BeaconChainError::BeaconStateError(e).into())
   177→    }
   178→}
