   378→/// Data column that we must custody and has completed kzg verification
   379→#[derive(Debug, Derivative, Clone, Encode, Decode)]
   380→#[derivative(PartialEq, Eq)]
   381→#[ssz(struct_behaviour = "transparent")]
   382→pub struct KzgVerifiedCustodyDataColumn<E: EthSpec> {
   383→    data: Arc<DataColumnSidecar<E>>,
   384→}
   385→
   386→impl<E: EthSpec> KzgVerifiedCustodyDataColumn<E> {
   387→    /// Mark a column as custody column. Caller must ensure that our current custody requirements
   388→    /// include this column
   389→    pub fn from_asserted_custody(kzg_verified: KzgVerifiedDataColumn<E>) -> Self {
   390→        Self {
   391→            data: kzg_verified.to_data_column(),
   392→        }
   393→    }
   394→
   395→    /// Verify a column already marked as custody column
   396→    pub fn new(
   397→        data_column: CustodyDataColumn<E>,
   398→        kzg: &Kzg,
   399→    ) -> Result<Self, (Option<ColumnIndex>, KzgError)> {
   400→        verify_kzg_for_data_column(data_column.clone_arc(), kzg)?;
   401→        Ok(Self {
   402→            data: data_column.data,
   403→        })
   404→    }
   405→
   406→    pub fn reconstruct_columns(
   407→        kzg: &Kzg,
   408→        partial_set_of_columns: &[Self],
   409→        spec: &ChainSpec,
   410→    ) -> Result<Vec<KzgVerifiedCustodyDataColumn<E>>, KzgError> {
   411→        let all_data_columns = reconstruct_data_columns(
   412→            kzg,
   413→            partial_set_of_columns
   414→                .iter()
   415→                .map(|d| d.clone_arc())
   416→                .collect::<Vec<_>>(),
   417→            spec,
   418→        )?;
   419→
   420→        Ok(all_data_columns
   421→            .into_iter()
   422→            .map(|data| {
   423→                KzgVerifiedCustodyDataColumn::from_asserted_custody(KzgVerifiedDataColumn { data })
   424→            })
   425→            .collect::<Vec<_>>())
   426→    }
