   443→/// Complete kzg verification for a `DataColumnSidecar`.
   444→///
   445→/// Returns an error if the kzg verification check fails.
   446→#[instrument(skip_all, level = "debug")]
   447→pub fn verify_kzg_for_data_column<E: EthSpec>(
   448→    data_column: Arc<DataColumnSidecar<E>>,
   449→    kzg: &Kzg,
   450→) -> Result<KzgVerifiedDataColumn<E>, (Option<ColumnIndex>, KzgError)> {
   451→    let _timer = metrics::start_timer(&metrics::KZG_VERIFICATION_DATA_COLUMN_SINGLE_TIMES);
   452→    validate_data_columns(kzg, iter::once(&data_column))?;
   453→    Ok(KzgVerifiedDataColumn { data: data_column })
   454→}
   455→
   456→/// Complete kzg verification for a list of `DataColumnSidecar`s.
   457→/// Returns an error for the first `DataColumnSidecar`s that fails kzg verification.
   458→///
   459→/// Note: This function should be preferred over calling `verify_kzg_for_data_column`
   460→/// in a loop since this function kzg verifies a list of data columns more efficiently.
   461→pub fn verify_kzg_for_data_column_list<'a, E: EthSpec, I>(
   462→    data_column_iter: I,
   463→    kzg: &'a Kzg,
   464→) -> Result<(), (Option<ColumnIndex>, KzgError)>
   465→where
   466→    I: Iterator<Item = &'a Arc<DataColumnSidecar<E>>> + Clone,
   467→{
   468→    let _timer = metrics::start_timer(&metrics::KZG_VERIFICATION_DATA_COLUMN_BATCH_TIMES);
   469→    validate_data_columns(kzg, data_column_iter)?;
   470→    Ok(())
   471→}
   472→
   473→#[instrument(skip_all, level = "debug")]
   474→pub fn validate_data_column_sidecar_for_gossip<T: BeaconChainTypes, O: ObservationStrategy>(
   475→    data_column: Arc<DataColumnSidecar<T::EthSpec>>,
   476→    subnet: DataColumnSubnetId,
   477→    chain: &BeaconChain<T>,
   478→) -> Result<GossipVerifiedDataColumn<T, O>, GossipDataColumnError> {
   479→    let column_slot = data_column.slot();
   480→    verify_data_column_sidecar(&data_column)?;
   481→    verify_index_matches_subnet(&data_column, subnet, &chain.spec)?;
   482→    verify_sidecar_not_from_future_slot(chain, column_slot)?;
   483→    verify_slot_greater_than_latest_finalized_slot(chain, column_slot)?;
   484→    verify_is_unknown_sidecar(chain, &data_column)?;
   485→
   486→    // Check if the data column is already in the DA checker cache. This happens when data columns
   487→    // are made available through the `engine_getBlobs` method.  If it exists in the cache, we know
   488→    // it has already passed the gossip checks, even though this particular instance hasn't been
   489→    // seen / published on the gossip network yet (passed the `verify_is_unknown_sidecar` check above).
   490→    // In this case, we should accept it for gossip propagation.
   491→    if chain
   492→        .data_availability_checker
   493→        .is_data_column_cached(&data_column.block_root(), &data_column)
   494→    {
   495→        // Observe this data column so we don't process it again.
   496→        if O::observe() {
   497→            observe_gossip_data_column(&data_column, chain)?;
   498→        }
   499→        return Err(GossipDataColumnError::PriorKnownUnpublished);
   500→    }

